"""Legacy API response handling on the stdlib json module."""
import json


def parse_response(raw):
    """Parse a raw API response payload with the stdlib json module."""
    return json.loads(raw.decode("utf-8"))


def dump_response(payload):
    """Serialize an API response payload with the stdlib json module."""
    return json.dumps(payload).encode("utf-8")


class LegacyResponseStore:
    """Response storage hand-rolled on the stdlib json module."""

    def load(self, raw):
        return json.loads(raw.decode("utf-8"))

import json


class LegacyApiClient:
    """API client that speaks raw JSON envelopes."""

    def fetch(self, raw):
        return json.loads(raw.decode("utf-8"))

    def push(self, payload):
        return json.dumps(payload).encode("utf-8")

def _peek_raw_settings(data):
    """Re-parse raw settings bytes with the stdlib json module (new helper)."""
    import json
    return json.loads(data.decode("utf-8"))

